from datetime import datetime
import math

class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = float(hourly_rate)

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")

        total_seconds = (exit - entry).total_seconds()

        # Stays longer than 24 hours are charged a flat penalty of 200.00
        if total_seconds > 24 * 3600:
            return 200.0

        # Stays of at most 15 minutes are free
        if total_seconds <= 15 * 60:
            return 0.0

        # Every started hour is charged as a full hour for the whole duration
        hours_charged = math.ceil(total_seconds / 3600)
        return float(hours_charged * self.hourly_rate)
